<script setup lang="ts">
import {ref,computed} from 'vue'
import {onShow,onLoad} from '@dcloudio/uni-app'
import WorkspaceShell from '../../components/WorkspaceShell.vue'
import AppIcon from '../../components/AppIcon.vue'
import OperatingCharts from './OperatingCharts.vue'
import {request,uuid,format} from '../../api'
import {work,resources,requireWorkspace,loadWorkspace,localDay,dayLabel,clock,money,type Row} from '../../workspace'
const busy=ref(false),error=ref(''),data=ref<Row|null>(null),frozen=ref<Row|null>(null),quarterId=ref(0),clinicId=ref(0),tab=ref('appointments'),sourceTab=ref('invoices'),initialReport=ref(0)
const role=computed(()=>work.data?.scope.role_code),group=computed(()=>work.data?.scope.scope_kind==='group')
const quarters=computed<Row[]>(()=>(resources.value.quarters||[]).map(q=>({...q,label:q.calendar_year+'年第'+q.quarter_no+'季度'})))
const clinics=computed(()=>[...(group.value?[{id:0,clinic_name:'集团全部门店'}]:[]),...(resources.value.clinics||[])])
const ops=computed(()=>data.value?.operations),history=computed(()=>(resources.value.reports||[]).filter(r=>r.quarter_id===quarterId.value))
const tabs=[{key:'appointments',name:'履约与原因'},{key:'continuity',name:'治疗接续'},{key:'skills',name:'技能供需'},{key:'standards',name:'标准核查'},{key:'finance',name:'季度财务'}]
const strataName:Record<string,string>={visit_kind:'初诊与接续',time_band:'就诊时段',clinic:'门店',treatment:'治疗类别',reason:'办理原因'}
const stratum=ref('visit_kind')
let analysisRequest=0
onLoad((q:any)=>{quarterId.value=Number(q?.quarter||0);initialReport.value=Number(q?.report||0);clinicId.value=Number(q?.clinic||0)})
onShow(async()=>{const ws=await requireWorkspace('UC12');if(!ws)return;if(!quarterId.value){const today=localDay();quarterId.value=quarters.value.find(q=>q.starts_on<=today&&q.ends_before>today)?.id||quarters.value[0]?.id||0}if(!group.value)clinicId.value=ws.scope.clinic_id||0;await analyze();if(initialReport.value){await readReport(initialReport.value);initialReport.value=0}})
async function analyze(){
 if(!quarterId.value)return
 const req=++analysisRequest
 busy.value=true
 error.value=''
 frozen.value=null
 data.value=null
 try{
  const response=await request('/api/reports?quarter_id='+quarterId.value+(clinicId.value?'&clinic_id='+clinicId.value:''))
  if(req===analysisRequest)data.value=response
 }catch(e:any){if(req===analysisRequest)error.value=e.message}
 finally{if(req===analysisRequest)busy.value=false}
}
async function readReport(id:number){
 const req=++analysisRequest
 busy.value=true
 error.value=''
 try{
  const response=await request('/api/reports/'+id)
  if(req===analysisRequest){frozen.value=response;tab.value='finance'}
 }catch(e:any){if(req===analysisRequest)error.value=e.message}
 finally{if(req===analysisRequest)busy.value=false}
}
function percentage(value:any){return value===null||value===undefined?'不适用':String(value)+'%'}
async function confirm(){if(!data.value||data.value.issues.length||role.value!=='director'||clinicId.value)return;const yes=await new Promise<boolean>(resolve=>uni.showModal({title:'确认季度财务来源',content:'本次固定收入、已复核成本、净利润、基金及来源版本。实时运营指标仍按查询时点展示。请核对季度与集团范围。',success:r=>resolve(r.confirm)}));if(!yes)return;busy.value=true;error.value='';try{const latest=[...history.value].sort((a,b)=>b.revision_no-a.revision_no)[0];const report=await request('/api/use-cases/UC12',{action:'confirm',quarter_id:quarterId.value,...(latest?{previous_report_id:latest.id}:{})},uuid());await loadWorkspace(true);await readReport(Number(report.id))}catch(e:any){error.value=e.message}finally{busy.value=false}}
</script>
<template><WorkspaceShell title="经营分析与季度财务" active="UC12" back>
 <view class="page-heading analytics-heading"><view><text class="page-title">经营分析与季度财务</text><text class="page-description">先看样本和来源，再判断履约、接续与经营结果。</text></view><button :disabled="busy" @click="analyze"><AppIcon name="refreshempty" :size="18"/> 刷新分析</button></view>
 <view class="analysis-filters analytics-toolbar">
  <label class="analytics-field"><text>归属季度</text><select v-model.number="quarterId" aria-label="归属季度" @change="analyze"><option v-for="q in quarters" :key="q.id" :value="q.id">{{q.label}}</option></select></label>
  <label v-if="group" class="analytics-field"><text>查看门店</text><select v-model.number="clinicId" aria-label="查看门店" @change="analyze"><option v-for="c in clinics" :key="c.id" :value="c.id">{{c.clinic_name}}</option></select></label>
  <view v-else class="analytics-field"><text>当前门店</text><text class="scope-clinic">{{clinics.find(c=>c.id===clinicId)?.clinic_name||'当前授权门店'}}</text></view>
  <text class="caption" v-if="ops">查询截止 {{dayLabel(ops.as_of)}} {{clock(ops.as_of)}}</text>
 </view>
 <view v-if="error" class="error">{{error}}</view><view v-if="busy&&!data" class="empty-state">正在核对业务来源…</view>
 <view class="view-tabs"><button v-for="item in tabs" :key="item.key" :class="{selected:tab===item.key}" @click="tab=item.key">{{item.name}}</button></view>
 <template v-if="ops">
 <template v-if="tab==='appointments'"><view class="metric-strip"><view><text class="caption">到期样本</text><text>{{ops.appointments.sample_count}}</text></view><view><text class="caption">患者取消率</text><text>{{percentage(ops.appointments.cancellation_rate)}}</text></view><view><text class="caption">核实未到率</text><text>{{percentage(ops.appointments.no_show_rate)}}</text></view><view><text class="caption">机构原因单列</text><text>{{ops.appointments.institutions}}</text></view></view><OperatingCharts v-if="data" :report="data"/><view class="method-note"><AppIcon name="info" :size="18"/><view><text>{{ops.definitions.due}}</text><text>{{ops.definitions.rates}}</text></view></view><view v-if="ops.appointments.unverified_count" class="attention">{{ops.appointments.unverified_count}} 条到期结果尚待核实，不能直接当作未到或完整季度结果。</view>
 <view class="surface report-section"><view class="section-bar"><text class="section-title">分层比较</text><picker :range="Object.values(strataName)" @change="stratum=Object.keys(strataName)[Number($event.detail.value)]"><button class="text-button">{{strataName[stratum]}} <AppIcon name="down" :size="14"/></button></picker></view><view class="comparison-header"><text>分层</text><text>样本</text><text>取消率</text><text>未到率</text></view><view v-for="row in ops.appointments.strata[stratum]||[]" :key="row.label" class="comparison-row"><text>{{format(row.label)}}</text><text>{{row.sample_count}}</text><text>{{percentage(row.cancellation_rate)}}</text><text>{{percentage(row.no_show_rate)}}</text></view><view v-if="!ops.appointments.sample_count" class="inline-empty">没有到期样本，比例不适用。</view><text class="section-footnote">{{ops.definitions.strata}}</text></view>
 <view class="surface report-section"><view class="section-bar"><text class="section-title">取消、未到及待核实来源</text></view><view v-for="r in ops.appointments.details" :key="r.id" class="source-line"><view><text>{{r.appointment_no}} · {{r.clinic_name}}</text><text class="caption">{{dayLabel(r.starts_at)}} {{clock(r.starts_at)}} · {{r.dentist_name}}</text><text class="caption">{{r.reason_description||'尚待核实实际结果'}}</text></view><text class="status-label">{{format(r.resolution)}}</text></view><view v-if="!ops.appointments.details.length" class="inline-empty">没有匹配的来源记录。</view></view>
 <view v-if="ops.appointments.institution_details.length" class="surface report-section"><view class="section-bar"><text class="section-title">机构不可履行与机构发起变更</text></view><view v-for="r in ops.appointments.institution_details" :key="r.id" class="source-line"><view><text>{{r.appointment_no}} · {{r.clinic_name}}</text><text class="caption">{{r.reason_description||'机构原因待核实'}}</text></view><text class="status-label">{{format(r.resolution)}}</text></view></view></template>
 <template v-if="tab==='continuity'"><view class="metric-strip"><view><text class="caption">应继续阶段</text><text>{{ops.continuity.sample_count}}</text></view><view><text class="caption">漏跟进</text><text>{{ops.continuity.missing_count}}</text></view><view><text class="caption">漏跟进率</text><text>{{percentage(ops.continuity.missing_rate)}}</text></view></view><view class="method-note"><AppIcon name="info" :size="18"/><text>{{ops.definitions.continuity}}</text></view><view class="phase-counts"><text v-for="(value,key) in ops.continuity.state_counts" :key="key">{{format(key)}} {{value}}</text></view><view class="surface report-section"><view class="section-bar"><text class="section-title">需要落实接续责任的阶段</text></view><view v-for="phase in ops.continuity.missing" :key="phase.id" class="source-line"><view><text>{{phase.phase_title}}</text><text class="caption">{{phase.plan_no}} · {{phase.clinic_name}}</text></view><text class="status-label">缺少有效跟进</text></view><view v-if="!ops.continuity.missing.length" class="inline-empty">当前没有核对出的漏跟进阶段；样本范围和查询时点见上方。</view></view></template>
 <template v-if="tab==='skills'"><view class="metric-strip"><view><text class="caption">未来需求时段</text><text>{{ops.skills.sample_count}}</text></view><view><text class="caption">当前无法承接</text><text>{{ops.skills.unmet_count}}</text></view></view><view class="method-note"><AppIcon name="info" :size="18"/><text>{{ops.definitions.skills}}</text></view><view class="surface report-section"><view v-for="r in ops.skills.rows" :key="r.id" class="source-line"><view><text>{{r.clinic_name}} · {{r.projects.join('、')||'初步检查'}}</text><text class="caption">{{dayLabel(r.starts_at)}} {{clock(r.starts_at)}}—{{clock(r.ends_at)}} · {{r.appointment_no}}</text><text class="caption">有效资格可用牙医 {{r.qualified_dentist_count}} 位 · {{r.resource_available?'有完整诊疗位':'诊疗资源不足'}}</text></view><text class="status-label">{{r.reason}}</text></view><view v-if="!ops.skills.rows.length" class="inline-empty">所选季度没有已登记的未来需求；不据此推断患者流失。</view></view></template>
 <template v-if="tab==='standards'"><view class="metric-strip"><view><text class="caption">实际项目样本</text><text>{{ops.standards.sample_count}}</text></view><view><text class="caption">待核查或需解释项目</text><text>{{ops.standards.review_count}}</text></view></view><view class="method-note"><AppIcon name="info" :size="18"/><text>临床追加、中止及已经批准的价格偏离也会列出供核对，不能把所有线索都认定为违规；这里不展示诊疗正文。</text></view><view class="surface report-section"><view v-for="r in ops.standards.rows" :key="r.id" class="source-line"><view><text>{{r.treatment_name}} · {{r.appointment_no}}</text><text class="caption">实际数量 {{Number(r.actual_quantity)}} · 实际单价 ¥{{money(r.charged_unit_price)}} · {{dayLabel(r.performed_at)}}</text><text class="review-reasons">{{r.reasons.join('；')}}</text></view></view><view v-if="!ops.standards.rows.length" class="inline-empty">所选样本未发现上述核查线索。</view></view></template>
 </template>
 <template v-if="tab==='finance'&&data"><view class="financial-heading"><view><text class="section-title">{{frozen?'已保存的季度版本':'当前季度核对结果'}}</text><text class="caption">{{frozen?'按原确认来源读取，不用当前价格或新修订替换历史':'已签署实际服务与已复核费用，按原归属季度计算'}}</text></view><button v-if="frozen" @click="frozen=null">返回当前核对</button><button v-else-if="role==='director'&&!clinicId" class="primary" :disabled="busy||data.issues.length>0" @click="confirm">正式确认财务版本</button></view>
 <view class="metric-strip finance-metrics"><view><text class="caption">{{(frozen?.scope_kind||data.scope_kind)==='group'?'集团净利润合计':'本店净利润合计'}}</text><text>¥{{money(frozen?(frozen.group_net_profit??frozen.net_profit):data.group_net_profit)}}</text></view><view v-if="(frozen?.scope_kind||data.scope_kind)==='group'"><text class="caption">集团激励基金 · 10%</text><text>{{Number(frozen?frozen.group_net_profit:data.group_net_profit)>0?'¥'+money(frozen?frozen.incentive_fund:data.incentive_fund):'不形成正向基金'}}</text></view></view>
 <OperatingCharts :report="frozen||data" finance :can-filter="group&&!clinicId&&!frozen" @filter="clinicId=$event;analyze()"/><view v-if="!frozen&&data.issues.length" class="attention"><text class="section-title">确认前需补齐</text><text v-for="issue in data.issues" :key="issue">{{issue}}</text></view><view v-if="frozen" class="method-note"><AppIcon name="locked" :size="18"/><text>财务版本 {{frozen.revision_no}} · {{format(frozen.confirmation_state)}} · {{dayLabel(frozen.as_of)}} {{clock(frozen.as_of)}}。实时运营指标不包含在本财务版本中。</text></view>
 <view class="surface report-section"><view v-for="row in (frozen?.rows||data.rows)" :key="row.dentist_id+'-'+row.clinic_id" class="finance-row"><view><text>{{row.dentist_name}} · {{row.clinic_name}}</text><text class="caption">收入 ¥{{money(row.revenue)}} · 医疗用品 ¥{{money(row.supplies_cost)}} · 运营费用 ¥{{money(row.operating_expense)}}</text></view><text>¥{{money(row.net_profit)}}</text></view><view v-if="!(frozen?.rows||data.rows).length" class="inline-empty">没有对应财务明细；费用缺报不能解释为零成本。</view></view>
 <view v-if="frozen" class="surface report-section"><view class="section-bar"><text class="section-title">固化的来源版本</text></view><view class="source-tabs"><button v-for="item in [{key:'invoices',name:'结算来源'},{key:'costs',name:'成本来源'},{key:'submissions',name:'齐备声明'}]" :key="item.key" :class="{selected:sourceTab===item.key}" @click="sourceTab=item.key">{{item.name}}</button></view><view v-for="(s,i) in frozen.sources[sourceTab]" :key="i" class="source-line"><view><text>{{sourceTab==='invoices'?s.invoice_no:sourceTab==='costs'?s.source_document_no:'齐备声明 '+s.id}}</text><text class="caption">保留版本 {{s.revision_no}} · {{sourceTab==='invoices'?'实际服务 '+dayLabel(s.started_at):sourceTab==='costs'?s.allocation_basis:'用品及运营费用分别报齐'}}</text></view><text v-if="sourceTab!=='submissions'">¥{{money(s.total_amount??s.allocated_amount)}}</text></view><view v-if="!frozen.sources[sourceTab].length" class="inline-empty">此版本在当前授权范围内没有该类来源。</view></view>
 <view class="report-history"><text class="section-title">已保存的财务版本</text><button v-for="r in history" :key="r.id" @click="readReport(r.id)"><text>版本 {{r.revision_no}} · {{format(r.confirmation_state)}}</text><AppIcon name="right" :size="16"/></button><text v-if="!history.length" class="caption">暂无已保存版本；暂算结果不会自动变成正式确认。</text></view></template>
</WorkspaceShell></template>
<style scoped>
.analytics-heading{border-radius:12px;padding:20px 23px;background:#e6f1fb;border:1px solid #d6e5f2}
.analytics-heading .page-title{color:#173b63}.analytics-heading .page-description{color:#395a78}
.analytics-toolbar{gap:12px;align-items:center}
.analytics-field{display:flex;align-items:center;gap:8px;color:#435b70;font-size:13px}
.analytics-field select,.scope-clinic{min-height:42px;border:1px solid #dbe5ed;border-radius:8px;background:#fff;color:#253347;font:inherit;padding:8px 11px}
.scope-clinic{display:inline-flex;align-items:center}


.analysis-filters{display:flex;align-items:center;gap:24px;flex-wrap:wrap;margin-bottom:24px}.filter-value{display:flex;align-items:center;gap:12px;border:1px solid #e3e8ef;background:#fff;border-radius:8px;min-height:48px;padding:10px 14px;font-size:14px}.filter-value>.caption{display:none}.metric-strip{display:flex;gap:30px;flex-wrap:wrap;padding:28px 0 24px}.metric-strip>view{min-width:140px;padding-left:17px;border-left:2px solid #e3e8ef}.metric-strip>view>text:last-child{display:block;margin-top:9px;font-size:27px;font-weight:600}.method-note{display:flex;align-items:flex-start;gap:11px;color:#758296;font-size:12px;line-height:1.9;margin:0 0 22px}.method-note>view>text{display:block}.report-section{margin:20px 0;box-shadow:none}.section-bar{padding:18px 22px;border-bottom:1px solid #e3e8ef;display:flex;align-items:center;justify-content:space-between;gap:14px}.section-bar>.section-title{font-size:16px}.comparison-header,.comparison-row{display:grid;grid-template-columns:2fr 1fr 1fr 1fr;gap:15px;padding:15px 22px;font-size:13px;align-items:center}.comparison-header{background:#f2f5f8;color:#758296;font-size:12px}.comparison-row{border-bottom:1px solid #e3e8ef}.comparison-row:last-child{border:0}.source-line,.finance-row{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;padding:19px 22px;border-bottom:1px solid #e3e8ef;font-size:14px;line-height:1.7}.source-line:last-child,.finance-row:last-child{border:0}.source-line .caption,.finance-row .caption{margin-top:5px}.source-line>.status-label{font-size:11px}.section-footnote{display:block;padding:14px 22px;color:#758296;font-size:11px}.inline-empty{padding:30px 22px;color:#758296;font-size:13px;text-align:center;line-height:1.9}.attention{display:flex;flex-direction:column;gap:9px;border-left:3px solid #9d681a;background:#fff;padding:17px 20px;margin:20px 0;font-size:13px;line-height:1.8}.attention>.section-title{font-size:15px}.phase-counts{display:flex;flex-wrap:wrap;gap:13px 22px;font-size:13px;color:#758296}.review-reasons{font-size:12px;display:block;margin-top:9px;color:#9d681a}.financial-heading{display:flex;align-items:center;justify-content:space-between;gap:18px;margin-top:28px}.financial-heading .caption{margin-top:6px}.financial-heading>button{font-size:13px;white-space:nowrap}.finance-row>text{font-weight:600;white-space:nowrap}.source-tabs{display:flex;gap:12px;padding:15px 22px;border-bottom:1px solid #e3e8ef}.source-tabs>button{border:0;background:transparent;font-size:13px;min-height:34px;padding:7px 10px}.source-tabs>button.selected{background:#edf5ff;color:#3278cf}.report-history{margin:28px 0}.report-history>.section-title{display:block;margin-bottom:17px;font-size:16px}.report-history>button{display:flex;align-items:center;justify-content:space-between;width:100%;padding:16px 0;border:0;border-bottom:1px solid #e3e8ef;background:transparent;border-radius:0;font-size:14px}@media(max-width:680px){.analysis-filters{gap:12px;margin-bottom:19px}.analysis-filters>picker{flex:1;min-width:140px}.filter-value{font-size:12px;gap:8px;padding:10px 12px;justify-content:space-between}.analysis-filters>.caption{font-size:10px}.page-heading{flex-wrap:wrap}.page-heading>button{font-size:12px}.metric-strip{gap:21px 12px;padding-top:24px}.metric-strip>view{min-width:calc(50% - 8px);padding-left:12px}.metric-strip>view>text:last-child{font-size:24px}.metric-strip .caption{font-size:11px}.comparison-header,.comparison-row{padding:14px 16px;gap:8px;font-size:11px;grid-template-columns:1.5fr .6fr .9fr .9fr}.section-bar{padding:16px}.section-bar>.section-title{font-size:15px}.source-line,.finance-row{padding:17px 16px;font-size:12px;gap:12px;flex-wrap:wrap}.source-line .caption,.finance-row .caption{font-size:10px}.method-note{font-size:11px}.financial-heading{flex-wrap:wrap}.financial-heading>.section-title{font-size:16px}.financial-heading>button{font-size:12px}.finance-metrics>view{min-width:0;flex:1}.finance-metrics>view>text:last-child{font-size:21px}.source-tabs{gap:5px;padding:12px}.source-tabs>button{font-size:12px;padding:8px}.section-footnote{padding:12px 16px}.inline-empty{font-size:12px}}
</style>
